import logging, unittest, warnings

def parse_age(text: str) -> int:
    age = int(text)
    if age < 0:
        raise ValueError(f"negative age: {age}")
    if age > 150:
        logging.getLogger("app").warning("suspicious age %d", age)
    return age

class TestParseAge(unittest.TestCase):
    def test_negative(self):
        with self.assertRaises(ValueError) as cm:
            parse_age("-3")
        self.assertIn("negative", str(cm.exception))

    def test_not_a_number(self):
        self.assertRaisesRegex(ValueError, "invalid literal", parse_age, "x")

    def test_logs_suspicious(self):
        with self.assertLogs("app", level="WARNING") as cm:
            parse_age("200")
        self.assertEqual(cm.output, ["WARNING:app:suspicious age 200"])

unittest.main(exit=False)           # ... Ran 3 tests ... OK

import tempfile, unittest
from pathlib import Path

class TestNotes(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        print("setUpClass once")

    def setUp(self):
        self.dir = Path(self.enterContext(tempfile.TemporaryDirectory()))
        self.file = self.dir / "notes.txt"
        self.file.write_text("hello")
        self.addCleanup(print, "cleanup for", self._testMethodName)

    def test_read(self):
        self.assertEqual(self.file.read_text(), "hello")

    def test_append(self):
        with self.file.open("a") as f:
            f.write("!")
        self.assertEqual(self.file.read_text(), "hello!")

unittest.main(exit=False)
# setUpClass once / cleanup for test_append / cleanup for test_read
# Ran 2 tests ... OK

import unittest

def is_leap(year: int) -> bool:
    return year % 4 == 0 and year % 100 != 0      # bug: ignores the 400 rule

class TestLeap(unittest.TestCase):
    def test_years(self):
        cases = [(2024, True), (2023, False), (1900, False), (2000, True)]
        for year, expected in cases:
            with self.subTest(year=year):
                self.assertEqual(is_leap(year), expected)

unittest.main(exit=False)
# FAIL: test_years (__main__.TestLeap.test_years) (year=2000)
# AssertionError: False != True
# Ran 1 test ... FAILED (failures=1)

import sys, unittest

class TestPlatform(unittest.TestCase):
    @unittest.skipIf(sys.platform == "win32", "uses POSIX paths")
    def test_posix_path(self):
        self.assertTrue("/tmp".startswith("/"))

    @unittest.skipUnless(sys.version_info >= (4, 0), "needs Python 4")
    def test_future(self):
        pass

    @unittest.expectedFailure
    def test_known_bug(self):
        self.assertEqual(round(2.675, 2), 2.68)   # float repr: gives 2.67

    def test_runtime_skip(self):
        self.skipTest("service not reachable")

