from unittest.mock import Mock, create_autospec, patch, seal

class Mailer:
    def send(self, to: str, subject: str) -> bool:
        return True

Mock().sennd("x")                             # plain Mock: typo silently accepted

strict = create_autospec(Mailer, instance=True)
strict.send("a@x.io", subject="hi")           # matches the real signature
for bad in (lambda: strict.sennd("x"), lambda: strict.send("a@x.io")):
    try:
        bad()
    except (AttributeError, TypeError) as e:
        print(type(e).__name__, str(e)[:45])
# AttributeError Mock object has no attribute 'sennd'
# TypeError missing a required argument: 'subject'

m = Mock()
m.client.get.return_value = 1
seal(m)
try:
    m.client.post
except AttributeError as e:
    print("sealed:", e)                        # sealed: mock.client.post

import io, unittest

class TestA(unittest.TestCase):
    def test_ok(self): pass
    def test_fail(self): self.assertEqual(1, 2)

class TestB(unittest.TestCase):
    @unittest.skip("not today")
    def test_skip(self): pass

class CountingResult(unittest.TextTestResult):
    def startTest(self, test):
        super().startTest(test)
        print("starting", test.id().split(".", 1)[1])

loader = unittest.TestLoader()
suite = unittest.TestSuite([loader.loadTestsFromTestCase(TestA),
                            loader.loadTestsFromTestCase(TestB)])
print(suite.countTestCases())                         # 3
runner = unittest.TextTestRunner(stream=io.StringIO(), resultclass=CountingResult)
result = runner.run(suite)
# starting TestA.test_fail / starting TestA.test_ok / starting TestB.test_skip
print(len(result.failures), len(result.skipped), result.wasSuccessful())  # 1 1 False

import unittest
from dataclasses import dataclass

@dataclass
class Money:
    amount: int
    currency: str

class TestMoney(unittest.TestCase):
    maxDiff = None

    def setUp(self):
        self.addTypeEqualityFunc(Money, self.assertMoneyEqual)

    def assertMoneyEqual(self, a, b, msg=None):
        if a.currency != b.currency:
            raise self.failureException(f"currency {a.currency} != {b.currency}")
        if a.amount != b.amount:
            raise self.failureException(f"{a.currency} amounts differ by {a.amount - b.amount}")

    def test_total(self):
        self.assertEqual(Money(1050, "EUR"), Money(1000, "EUR"))

unittest.main(exit=False)
# AssertionError: EUR amounts differ by 50
